/**
 * Iron & Ink — the printed aftercare guide (A4, one page).
 *
 * Vera hands this sheet over the counter at the end of the session.
 * Its body is not written here: the day-by-day healing timeline is
 * generated by `CareTimeline` from the care-phase data, so the guide
 * is exactly as long as the phases say it is — five phases, one page.
 * Around the timeline: who the sheet belongs to, the warning panel,
 * and the studio's number, big enough to find with sore eyes.
 */
import {
  Column,
  Divider,
  Document,
  Heading,
  List,
  ListItem,
  PageFooter,
  PageNumber,
  Row,
  Text,
  token,
} from "@hyper-elements/react";
import { artist, booking, carePhases, chosenDesign, client, guideFinePrint, studio, warningSigns } from "./data";
import { palette, ironTheme, webFonts } from "./theme";
import { CareTimeline } from "./care";
import { StudioMark } from "./studio";

export default function AftercareGuide() {
  return (
    <Document
      size="A4"
      orientation="portrait"
      margin={[34, 44, 30, 44]}
      theme={ironTheme}
      title={`Aftercare guide — ${chosenDesign.name} for ${client.fullName}, ${studio.fullName}`}
      lang="en"
      fonts={webFonts}
      style={{ fontSize: 12.5, lineHeight: 1.5, gap: 10 }}
    >
      {/* Whose sheet this is. */}
      <Row style={{ alignItems: "start", justifyContent: "space-between", gap: 24 }}>
        <StudioMark compact />
        <Column style={{ gap: 2, alignItems: "end" }}>
          <Text style={{ apply: ["eyebrow"], color: palette.blood }}>Aftercare guide</Text>
          <Text style={{ fontSize: 12, color: token("colors.muted") }}>
            For {client.fullName} · {chosenDesign.name} ({chosenDesign.no}) · {booking.placement}
          </Text>
          <Text style={{ fontSize: 12, color: token("colors.muted") }}>
            Tattooed by {artist.name} · {booking.dateLabel}
          </Text>
        </Column>
      </Row>

      <Column style={{ gap: 6 }}>
        <Heading level={1} style={{ fontSize: 27, lineHeight: 1.1 }}>
          Healing your {chosenDesign.name.toLowerCase()}
        </Heading>
        <Text style={{ fontSize: 12, lineHeight: 1.55, color: token("colors.muted") }}>
          A tattoo is a wound with a picture in it. The first four weeks decide how it looks for the next forty
          years — follow the phases in order, and when a phase and your skin disagree, call the studio and trust
          the studio.
        </Text>
      </Column>

      <Divider style={{ borderTop: { width: 2, style: "solid", color: palette.ink } }} />

      {/* The timeline: generated from the care phases. */}
      <CareTimeline phases={carePhases} />

      {/* When to call. */}
      <Row style={{ gap: 20, alignItems: "stretch" }}>
        <Column
          style={{
            backgroundColor: palette.ink,
            color: palette.bone,
            borderRadius: 6,
            padding: [14, 18],
            gap: 8,
          }}
        >
          <Text style={{ apply: ["eyebrow"], color: palette.blood }}>Call the studio if you notice</Text>
          <List style={{ gap: 3, fontSize: 11.5, lineHeight: 1.45, indent: 16 }}>
            {warningSigns.map((sign) => (
              <ListItem key={sign}>{sign}</ListItem>
            ))}
          </List>
        </Column>
        <Column style={{ width: 218, flex: "none", gap: 4, justifyContent: "center" }}>
          <Text style={{ apply: ["metaLabel"] }}>The studio, any time</Text>
          <Text
            style={{
              fontFamily: token("fonts.heading"),
              fontSize: 25,
              fontWeight: 700,
              letterSpacing: 0.6,
              lineHeight: 1.15,
            }}
          >
            {studio.phone}
          </Text>
          <Text style={{ fontSize: 11.5, lineHeight: 1.5, color: token("colors.muted") }}>
            {studio.address}. Advice about a healing tattoo is always free — never sit at home worrying.
          </Text>
        </Column>
      </Row>

      {/* Fine print. */}
      <Column style={{ gap: 3, padding: [8, 0, 0], border: { top: `1px solid ${palette.border}` } }}>
        {guideFinePrint.map((line) => (
          <Text key={line} style={{ fontSize: 9.5, lineHeight: 1.45, color: token("colors.muted") }}>
            {line}
          </Text>
        ))}
      </Column>

      <PageFooter style={{ padding: [8, 0, 0], border: { top: `1px solid ${palette.border}` } }}>
        <Row style={{ gap: 16 }}>
          <Text style={{ fontSize: 9.5, color: token("colors.muted") }}>
            {studio.fullName} · {studio.address} · {studio.phone} · {studio.email}
          </Text>
          <Text style={{ width: 110, textAlign: "right", fontSize: 9.5, color: token("colors.muted") }}>
            Page <PageNumber /> of <PageNumber total />
          </Text>
        </Row>
      </PageFooter>
    </Document>
  );
}
